package dev.qperiapt.continuity.android.tests;

import android.os.Bundle;
import java.io.File;

/** Bounded public approvals; all device private state is generated by the installed app. */
final class RootInputs {
    private RootInputs() { }
    static void install(File inputs,Bundle arguments,String operation,String profile) throws Exception {
        WitnessInputs.install(inputs,arguments);
        WitnessInputs.installAuthority(inputs,arguments,operation);
        if(operation.startsWith("root-target-")||operation.startsWith("root-original-target-")) {
            String leaf=operation.startsWith("root-original-target-")?"root-original-target":"root-target";
            File target=new File(inputs,leaf);
            if(operation.endsWith("-create")) {
                if(!target.mkdir())throw new IllegalStateException("new root input directory");
                Bundle fields=new Bundle(arguments);fields.putString("operation","policy-create");
                PolicyInputs.initial(target,fields,profile);
            } else {
                if(!target.isDirectory())throw new IllegalStateException("original root inputs absent");
                String[] names={"grant-certificate","grant-roster","trusted-account","trusted-roster-version","trusted-roster-digest"};
                int[] minimum={1,1,32,8,32},maximum={8192,8192,32,8,32};
                for(int i=0;i<names.length;++i)WitnessInputs.install(target,arguments,names[i],minimum[i],maximum[i],true);
            }
            return;
        }
        // Stages may add approvals but can never replace a retained original approval.
        String[] names={"root-route","root-plan","root-next-plan","root-winner","root-noncommit","root-freeze","root-retirement",
            "root-inventory-receipt","root-report-proposal","root-report-receipt","root-ack"};
        int[] minimum={8,8,8,8,3449,1,3449,3690,353,3730,3730};
        int[] maximum={16,131072,131072,65536,3449,131072,3449,3690,353,3730,3730};
        for(int i=0;i<names.length;++i)if(arguments.containsKey(names[i]))
            WitnessInputs.install(inputs,arguments,names[i],minimum[i],maximum[i],true);
        if(operation.equals("root-begin-unknown")) {
            WitnessInputs.install(inputs,arguments,"connection-session",32,32,true);
            WitnessInputs.install(inputs,arguments,"connection-message",32,32,true);
        }
        if(operation.startsWith("root-peer-"))PeerInputs.install(new File(inputs,"root-target"),arguments,operation.substring(5));
    }
}
